import type { TemplateContext } from '../types';

export function backendReadme(ctx: TemplateContext): string {
  return [
    `# ${ctx.contract.projectName} — Backend`,
    '',
    'Generated by DevFlow.',
    '',
    '## Quick start',
    '',
    '```bash',
    'npm install',
    'npm run start:dev',
    '```',
    '',
    'The API listens on http://localhost:4001 by default.',
    '',
    '## Project structure',
    '',
    '```',
    '.',
    '├── src/',
    '│   ├── main.ts                     # Application entrypoint',
    '│   ├── app.module.ts               # Root module',
    '│   └── modules/',
    '│       └── core/',
    '│           ├── core.module.ts',
    '│           ├── core.controller.ts',
    '│           ├── core.service.ts',
    '│           └── dto/',
    '│               └── create-item.dto.ts',
    '├── nest-cli.json',
    '├── tsconfig.build.json',
    '├── package.json',
    '└── README-backend.md',
    '```',
    '',
    '## Available scripts',
    '',
    '| Command | Description |',
    '|---------|-------------|',
    '| `npm run start:dev` | Hot-reload development |',
    '| `npm run build` | Production build |',
    '| `npm run start` | Start production server |',
    '',
    '## Tech stack',
    '',
    '- **Framework:** NestJS 10',
    '- **Language:** TypeScript',
    '- **Database:** PostgreSQL via Prisma',
  ].join('\n');
}
